          {navItems.map((item) => (
             <a 
               key={item} 
               href={`#${item.toLowerCase()}`}
               className="relative after:content-[''] after:absolute after:w-full after:scale-x-0 after:h-0.5 after:bottom-0 after:left-0 after:bg-black dark:after:bg-neo-blue after:origin-bottom-right after:transition-transform after:duration-300 hover:after:scale-x-100 hover:after:origin-bottom-left dark:text-gray-200 hover:text-black dark:hover:text-neo-blue transition-colors"
             >
               {item}
             </a>
          ))}

          <button 
            onClick={toggleTheme}
