        </div>

        {/* Mobile Buttons */}
        <div className="flex items-center gap-4 md:hidden">
          <button 
              onClick={toggleTheme}
              className="p-2 border-2 border-black dark:border-white dark:text-white hover:bg-neo-yellow dark:hover:bg-neo-dark-surface dark:hover:text-neo-yellow transition-all dark:shadow-[3px_3px_0px_0px_#7ED957] active:translate-y-1 active:shadow-none"
