                   rel="noopener noreferrer"
                   className={`flex items-center gap-3 p-4 border-2 border-black font-bold text-lg shadow-neo hover:translate-x-[2px] hover:translate-y-[2px] transition-all ${contact.color}`}
                 >
                   {contact.icon}
                   {contact.name}
