                              <Check className="text-green-600 drop-shadow-md bg-white rounded-full p-0.5" strokeWidth={4} size={20} />
                           </div>
                        )}
                     </div>
                     <div className="flex-1 flex flex-col justify-between">
                        <div>
                          <div className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Book {idx + 1}</div>
                          <h4 className="font-bold text-sm md:text-base leading-tight mb-1 dark:text-white">{book.title}</h4>
                        </div>

                        {book.status === 'read' && (
                           <a href={book.url} target="_blank" rel="noopener noreferrer" className="text-xs font-bold underline decoration-2 decoration-neo-warm-coral hover:text-neo-warm-coral transition-colors w-max">
